'use strict';

// MODULES // 

var ln = require( '@stdlib/math/base/special/ln' );
var exp = require( '@stdlib/math/base/special/exp' );

// MAIN //

/**
* Logirethmic scale.
*
* @param {Array} mnmx - minmax array 
* @param {Number} points - number of points to generat in range
* @returns {Array} Points between range with linear scale
*/
function LogirithemicScale( mnmx, points ) {
	var logMn;
	var logMx;
	var steps;
    var arr;
	var val;
	var i;
	
	arr = [];
	logMn = ln( mnmx[ 0 ] );
	logMx = ln( mnmx[ 1 ] );
	steps = ( logMx - logMn ) / points;

	for ( i = 0; i < points; i++ ) {
		arr.push( exp( logMn + steps * i ) );
	}
	return arr;
}

// EXPORT //

module.exports = LogirithemicScale;